updated_count = 0
for t in topics:
    top_id = t.get("topic", "")
    if top_id in PEETH_SUMMARIES:
        t["summary"] = PEETH_SUMMARIES[top_id]
        updated_count += 1
    else:
        # Clean remaining topics of prompt phrases
        s = t.get("summary", "")
        s = re.sub(r"सिर्फ इसी एक [^।]*कहानी बनाओ[^।]*।?", "", s).strip()
        s = re.sub(r"\(यह शक्तिपीठों की भूमिका वाली[^)]*\)", "", s).strip()
        t["summary"] = s

print(f"Updated {updated_count} Shaktipeeth summaries!")

with open(path, "w", encoding="utf-8") as f:
    json.dump(topics, f, ensure_ascii=False, indent=2)

print("Saved clean, unique topics to", path)
